 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    # The four diagonal markers around each 2x2 object rotate into rays
    # pointing outward from the object.
    for r, c in blocks:
        points = [
            (r - 1, c - 1, (r + 2, c - 1), -1, -1),  # upper-left <- lower-left
            (r - 1, c + 2, (r - 1, c - 1), -1,  1),  # upper-right <- upper-left
            (r + 2, c - 1, (r + 2, c + 2), 1, -1),   # lower-left <- lower-right
            (r + 2, c + 2, (r - 1, c + 2), 1,  1),   # lower-right <- upper-right
        ]
        for sr, sc, (fr, fc), dr, dc in points:
            if not (0 <= sr < h and 0 <= sc < w and 0 <= fr < h and 0 <= fc < w):
                continue
            color = grid[fr][fc]
            rr, cc = sr, sc
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
